teacher_question_label(
    'IM-G3-U3-L13',
    labeled_question(advancing, "It is often helpful to get a sense of a quantity (how many, how much, how long, etc.), with groups of 10 or groups of 100. Numbers that are groups of 10, such as 50 and 90, can be called ‘multiples of 10.’ Numbers that are groups of 100, such as 200 and 700, can be called ‘multiples of 100.’", region_type('activity_synthesis'), source_path('curriculum/im_teacher_guides/grade3/unit3/lesson13.md'), source_file_sha256('d9446bd33caeadb1e90e581fe60e5b50e54c6e8aab8b0ad58d1bdb158c43cafd'), source_byte_span(7887, 8514), label_origin(machine_classification), review_status(pending_human_review))).

