teacher_question_label(
    'IM-G3-U4-L19',
    labeled_question(advancing, "“Was it necessary to decompose any of the tens into ones to divide?” (It wasn’t necessary for 63 ÷ 3 because there was already the right number of tens and ones to put into 3 groups. It wasn’t necessary for 100 ÷ 5 because I started with 10 tens and there was already the right number of tens to put into 5 groups.)", region_type('activity_synthesis'), source_path('curriculum/im_teacher_guides/grade3/unit4/lesson19.md'), source_file_sha256('e607d3ad0bb15621355bc37e338a546be64ab83307909a51052e7b4721254089'), source_byte_span(12111, 12810), label_origin(machine_classification), review_status(pending_human_review))).

